mapper.select:
select * from ( SELECT a.pack_id packId, a.company_id companyId, DATE_FORMAT( a.begin_date, '%Y-%m-%d' ) beginDate, DATE_FORMAT( a.end_date, '%Y-%m-%d' ) endDate, DATE_FORMAT( a.pack_time, '%Y-%m-%d %H:%i:%s' ) packTime, ifnull(a.pack_status, 0) packStatus, DATE_FORMAT( a.download_expire_time, '%Y-%m-%d' ) downloadExpireTime, a.oper_user_id oprtUserId, DATE_FORMAT( a.oper_time, '%Y-%m-%d %H:%i:%s' ) operTime, b.company_name companyName, u.user_name userName, CASE WHEN ifnull(a.pack_status, 0) = 2 THEN '查看' ELSE '' END downloadAddress FROM ecg_out_pack_rec a LEFT JOIN comm_company b ON a.company_id = b.company_id LEFT JOIN comm_system_user u ON a.oper_user_id = u.user_id where a.company_id in(select distinct company_id from comm_user_mng_dept a INNER JOIN comm_dept b ON a.dept_id = b.dept_id where user_id=#{loginUserId} ) )temp where 1=1
and DATE_FORMAT(operTime,'%Y-%m-%d') >= #{tm}
and DATE_FORMAT(operTime,'%Y-%m-%d') <= #{tm}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by packTime desc
